        VkPerformanceConfigurationAcquireInfoINTEL $acquireInfo,
    ): VkPerformanceConfigurationINTEL {
        $nativeAcquireInfo = $acquireInfo->toCData($this->memory);

        $nativeConfiguration = $this->memory->new('VkPerformanceConfigurationINTEL');

        $procedure = $this->vkGetInstanceProc('vkAcquirePerformanceConfigurationINTEL', $device);

        $this->assertSuccess('vkAcquirePerformanceConfigurationINTEL', $procedure($device->pointer, \FFI::addr($nativeAcquireInfo), \FFI::addr($nativeConfiguration)));

