        $devicePointer = $device->pointer;

        return new VkPerformanceConfigurationINTEL($this, $nativeConfiguration, $device, function (Handle $handle) use ($destroy, $devicePointer): void {
            $destroy($devicePointer, $handle->pointer);
        });
    }

