    /**
     * @see https://registry.khronos.org/vulkan/specs/latest/man/html/vkAllocateCommandBuffers.html
     * @since 1.0
     *
     * @api
     *
     * @return list<VkCommandBuffer>
     * @throws CommandFailedException in case of the command fails
     */
    public function vkAllocateCommandBuffers(VkDevice $device, VkCommandBufferAllocateInfo $allocateInfo): array
    {
        $nativeAllocateInfo = $allocateInfo->toCData($this->memory);

        $total = $allocateInfo->commandBufferCount;
        $nativeCommandBuffers = $this->memory->new('VkCommandBuffer[' . \max(1, $total) . ']');

        $procedure = $this->vkGetInstanceProc('vkAllocateCommandBuffers', $device);

        $this->assertSuccess('vkAllocateCommandBuffers', $procedure($device->pointer, \FFI::addr($nativeAllocateInfo), $nativeCommandBuffers));

        $created = [];
        for ($index = 0; $index < $total; ++$index) {
            /** @var CData $element */
            $element = $nativeCommandBuffers[$index];

            $created[] = new VkCommandBuffer($this, $element, $device);
        }

        return $created;
    }

