    public function vkAllocateMemory(VkDevice $device, VkMemoryAllocateInfo $allocateInfo): VkDeviceMemory
    {
        $nativeAllocateInfo = $allocateInfo->toCData($this->memory);

        $nativeMemory = $this->memory->new('VkDeviceMemory');

        $procedure = $this->vkGetInstanceProc('vkAllocateMemory', $device);

        $this->assertSuccess('vkAllocateMemory', $procedure($device->pointer, \FFI::addr($nativeAllocateInfo), null, \FFI::addr($nativeMemory)));

        $destroy = $this->vkGetInstanceProc('vkFreeMemory', $device);
        $devicePointer = $device->pointer;

        return new VkDeviceMemory($this, $nativeMemory, $device, function (Handle $handle) use ($destroy, $devicePointer): void {
            $destroy($devicePointer, $handle->pointer, null);
        });
    }

